entity.extra-code-model:

public com.educaflow.subsystem.common.db.CentroUsuario getCentroUsuario(com.educaflow.subsystem.common.db.Centro centro) {
    if (centro == null || centro.getId() == null || centroUsuarios == null) {
        return null;
    }
    return centroUsuarios.stream()
        .filter(cu -> cu.getCentro() != null && centro.getId().equals(cu.getCentro().getId()))
        .findFirst()
        .orElse(null);
}
